mapper.select:

SELECT w.id AS workorder_id,w.planned_qty,COALESCE(SUM(e.target_qty),0) AS allocated_target_qty,
       w.planned_qty-COALESCE(SUM(e.target_qty),0) AS remaining_target_qty,
       GREATEST(COALESCE(SUM(e.target_qty),0)-w.planned_qty,0) AS excess_target_qty,COUNT(e.id) AS execution_count
FROM workorder w LEFT JOIN mes_production_execution e ON e.workorder_id=w.id AND e.status!=#{cancelled}
AND e.id!=#{excluding}
WHERE w.id=#{id} GROUP BY w.id,w.planned_qty
